import { readFileSync } from 'node:fs'
import { typeFromText } from './tool-norm.ts'

const rows = JSON.parse(readFileSync(process.argv[2], 'utf8'))
const kinds: Record<string, number> = {}
let both = 0
for (const r of rows) {
  if (r.basis !== 'both' || !r.declared) continue
  both++
  let n: any = typeFromText(r.declared)
  if (n.k === 'union') {
    const rest = n.members.filter((m: any) => !(m.k === 'prim' && m.name === 'undefined'))
    n = rest.length === 1 ? rest[0] : n
  }
  const strong = n.k === 'name' ? 'name' : n.k === 'union' && n.members.every((m: any) => m.k === 'name' || (m.k === 'prim' && m.name === 'undefined')) ? 'union of names' : n.k
  kinds[strong] = (kinds[strong] ?? 0) + 1
}
console.log('agreed both', both, JSON.stringify(kinds))
for (const [prefix, pred] of [
  ['wrong', (r: any) => r.tool?.outcome === 'wrong'],
  ['missing', (r: any) => r.tool?.outcome === 'missing'],
  ['no reference', (r: any) => r.tool?.outcome === 'no reference'],
] as const) {
  for (const r of rows.filter(pred)) {
    console.log(prefix, r.corpus, `${r.component}.${r.prop}`, '| origin', r.origin, '| A:', String(r.checker).slice(0, 90), '| B:', String(r.declared).slice(0, 70))
  }
}

